const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('fr-FR').format(Number(n||0))+' F CFA';
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Une erreur est survenue.');return data}
function showDashboard(user){$('#login').hidden=true;$('#dashboard').hidden=false;$('#admin-name').textContent=user?.name||'Administrateur';ensureAdminBackButtons();refresh();loadQuotaOffers()}
async function refresh(){try{const d=await api('/api/admin/summary');$('#users').textContent=money(d.users).replace(' F CFA','');$('#user-split').textContent=`${d.active_users} actifs · ${d.suspended_users} suspendus` ;$('#pending-deposits').textContent=d.pending_deposits;$('#approved-deposits').textContent=d.approved_deposits;$('#deposit-total').textContent='Montant validé : '+money(d.approved_deposit_total_cfa);$('#commissions').textContent=d.commissions;$('#commission-total').textContent='Montant total : '+money(d.commissions_total_cfa);$('#cash-held').textContent=money(d.cash_held_cfa);$('#wallets-due').textContent=money(d.user_wallets_due_cfa);$('#invested-funds').textContent=money(d.invested_funds_cfa);$('#smile-net').textContent=money(d.smile_net_funds_cfa);$('#pending-withdrawals').textContent=d.pending_withdrawals;$('#pending-withdrawals-total').textContent=money(d.pending_withdrawals_cfa);$('#paid-withdrawals').textContent=money(d.withdrawals_paid_cfa);$('#pending-investments').textContent=d.pending_investments;$('#investments-total').textContent='Validés : '+money(d.investments_approved_cfa);$('#withdrawal-fees').textContent=money(d.withdrawal_fees_cfa);$('#refresh-status').textContent='Comptabilité actualisée — '+d.accounting_basis+'.'}catch(e){$('#refresh-status').textContent=e.message}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';const f=new FormData(e.currentTarget);try{const d=await api('/api/auth/login?space=admin',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});if(d.user?.role!=='admin'){await api('/api/auth/logout?space=admin',{method:'POST'});throw new Error('Ce compte ne dispose pas des droits administrateur.')}showDashboard(d.user)}catch(err){$('#login-error').textContent=err.message}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/auth/logout?space=admin',{method:'POST'})}finally{location.reload()}});
api('/api/auth/me?space=admin').then(d=>{if(d.user?.role==='admin')showDashboard(d.user)}).catch(()=>{});


// Navigation souple entre les rubriques de l’administration.
const smileAdminSectionStack=[];let smileCurrentAdminSection='overview';
const smileAdminTitles={overview:'Vue générale',offers:'Offres d’investissement',limited:'Gestion des temps limités',publications:'Publications et annonces',finance:'Gestion financière',payments:'Supervision des paiements', 'deposit-settings':'Gestion des dépôts',accounts:'Comptes & parrainage',support:'Service client',reports:'Comptabilité & rapports',control:'Contrôle'};
function ensureAdminBackButtons(){
 document.querySelectorAll('.admin-panel[data-panel]').forEach(panel=>{
  if(panel.dataset.panel==='overview'||panel.querySelector('.admin-smart-back'))return;
  const btn=document.createElement('button');btn.type='button';btn.className='outline admin-smart-back';btn.innerHTML='<span aria-hidden="true">←</span> Retour';btn.setAttribute('aria-label','Revenir à la rubrique précédente');
  btn.addEventListener('click',()=>{if(history.state?.smileAdminSection&&history.state.smileAdminSection!=='overview'){history.back();return}const previous=smileAdminSectionStack.pop()||'overview';openAdminSection(previous,{fromBack:true})});
  panel.insertBefore(btn,panel.firstChild);
 });
}
function openAdminSection(name,opts={}){
  if(!opts.fromBack&&name!==smileCurrentAdminSection){smileAdminSectionStack.push(smileCurrentAdminSection);history.pushState({smileAdminSection:name},'',`#admin-${encodeURIComponent(name)}`)}else if(opts.fromBack&&history.state?.smileAdminSection)history.replaceState({smileAdminSection:name},'',`#admin-${encodeURIComponent(name)}`);
  smileCurrentAdminSection=name;
  if(name==='offers') loadAdminOffers();
  if(name==='limited') loadAdminOffers();
  if(name==='publications') loadAdminPublications();
  if(name==='accounts') loadAdminUsers();
  if(name==='finance') { loadDeposits(); loadWithdrawals(); loadAdminInvestments(); }
  if(name==='payments') loadPaymentSupervision();
  if(name==='deposit-settings') loadDepositSettings();
  if(name==='reports') { runFinancialReport(); }
  if(name==='control') { $('#control-content').hidden=true; }
  if(name==='support') { loadSupportMessages(); loadAdminNotifications(); }
  document.querySelectorAll('[data-panel]').forEach(panel=>{const active=panel.dataset.panel===name;panel.hidden=!active;panel.classList.toggle('active',active)});
  document.querySelectorAll('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.section===name));
  const titles={payments:['Supervision des paiements','Suivi Flooz/Mixx (TMoney), anomalies et rapprochement des opérations.'],'deposit-settings':['Gestion des dépôts','Configuration des numéros de réception Flooz et Mixx.'],overview:['Vue générale','Suivi synthétique de l’activité SMILE.'],finance:['Gestion financière','Dépôts, retraits et investissements.'],accounts:['Comptes & parrainage','Gestion des utilisateurs et du réseau de parrainage.'],support:['Service client','Messages et notifications de la plateforme.'],reports:['Comptabilité & rapports','Trésorerie, soldes dus et mouvements comptables.'],control:['Contrôle','Gestion sécurisée des comptes spéciaux et de leurs commissions.'],offers:['Offres d’investissement','Création, modification et activation des offres.'],limited:['Gestion des temps limités','Administration des produits SM Durée limitée.'],publications:['Publications et annonces','Rédaction, publication et retrait des actualités visibles aux utilisateurs.']};
  const t=titles[name]||titles.overview;$('#section-title').textContent=t[0];$('#section-description').textContent=t[1];
  ensureAdminBackButtons();
}
history.replaceState({smileAdminSection:'overview'},'',location.pathname+location.search+location.hash);
window.addEventListener('popstate',event=>{const target=event.state?.smileAdminSection||smileAdminSectionStack.pop()||'overview';const idx=smileAdminSectionStack.lastIndexOf(target);if(idx>=0)smileAdminSectionStack.splice(idx);openAdminSection(target,{fromBack:true})});
document.querySelectorAll('.nav-item').forEach(btn=>btn.addEventListener('click',()=>openAdminSection(btn.dataset.section)));
document.querySelectorAll('[data-goto]').forEach(btn=>btn.addEventListener('click',()=>openAdminSection(btn.dataset.goto)));

async function loadQuotaOffers(){try{const d=await api('/api/admin/offers');$('#quota-offer').innerHTML=d.offers.map(o=>`<option value="${o.id}">${o.name} — ${o.duration_label}</option>`).join('')}catch(e){$('#quota-status').textContent=e.message;$('#global-quota-status').textContent=e.message}}
$('#quota-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),id=String(f.get('publicId')).trim(),offer=String(f.get('offerId')),limit=Number(f.get('limit')),reason=String(f.get('reason')).trim();$('#quota-status').textContent='Enregistrement…';try{const result=await api(`/api/admin/users/${encodeURIComponent(id)}/offers/${offer}/quota`,{method:'PUT',body:JSON.stringify({limit,reason})});$('#quota-status').textContent=`Limite personnelle enregistrée : ${result.limit} au total, ${result.used} déjà utilisée(s), ${result.remaining} restante(s). Le membre doit actualiser son compte pour voir la nouvelle limite. Historique et motif conservés.`;await loadQuotaAudit()}catch(err){$('#quota-status').textContent=err.message}});
$('#global-quota-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),remaining=Number(f.get('remaining')),reason=String(f.get('reason')).trim();if(!f.get('confirmGlobal')){ $('#global-quota-status').textContent='Cochez la confirmation pour continuer.';return}if(!confirm('Confirmer la mise à jour de la limite personnelle pour TOUS les utilisateurs, anciens et nouveaux, sur TOUTES les offres SMILE ? Les limites déjà consommées seront conservées et les limites par défaut seront mises à jour.'))return;const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;$('#global-quota-status').textContent='Mise à jour globale en cours…';try{const result=await api('/api/admin/quotas/global',{method:'PUT',body:JSON.stringify({remaining,reason,confirmed:true})});$('#global-quota-status').textContent=`Limite personnelle appliquée à ${result.updatedUsers} utilisateur(s) et ${result.updatedQuotas} quota(s). Quotas consommés conservés; toutes les valeurs par défaut sont mises à jour.`;e.currentTarget.reset();$('#quota-form [name="publicId"]').value='';await loadQuotaAudit()}catch(err){$('#global-quota-status').textContent=err.message}finally{button.disabled=false}});

// Gestion complète des offres depuis l'administration.
function renderLimitedAdminOffers(){const host=$('#limited-offer-list');if(!host)return;host.innerHTML='';const rows=(window.smileAdminOffers||[]).filter(o=>o.category==='limited');if(!rows.length){host.textContent='Aucun produit à durée limitée.';return}for(const o of rows){const card=document.createElement('article');card.className='offer-row';const info=document.createElement('div');info.className='offer-row-info';const title=document.createElement('b');title.textContent=o.name+' · '+o.code;const meta=document.createElement('p');meta.textContent=`${o.duration_label} · ${money(o.min_amount_cfa)} · profit affiché ${money(o.display_value_cfa)} · stock ${o.stock_limit===null?'illimité':Math.max(0,Number(o.stock_limit)-Number(o.stock_used))+' / '+o.stock_limit} · réservations restantes ${Number(o.reservations_remaining)||0}`;const status=document.createElement('p');status.className='offer-publication-status';status.textContent=o.removed?'Retiré du catalogue':(!o.published?'Brouillon — non visible':(!o.purchase_enabled?'Suspendu':'Publié')) ;info.append(title,meta,status);const edit=document.createElement('button');edit.className='outline';edit.type='button';edit.textContent='Modifier / programmer';edit.onclick=()=>{openAdminSection('offers');fillOfferForm(o);};card.append(info,edit);host.append(card)}}
$('#limited-new-product')?.addEventListener('click',()=>{openAdminSection('offers');resetOfferForm();$('#offer-form').elements.category.value='limited';});
async function loadAdminOffers(){try{const d=await api('/api/admin/offers');window.smileAdminOffers=d.offers||[];renderLimitedAdminOffers();const previewButton=$('#preview-user-space');if(previewButton)previewButton.disabled=!window.smileAdminOffers.length;const host=$('#offer-list');host.innerHTML='';if(!d.offers.length){host.textContent='Aucune offre créée.';return}for(const o of d.offers){const card=document.createElement('article');card.className='offer-row';const title=document.createElement('div');title.className='offer-row-info';const h=document.createElement('b');h.textContent=o.name+' · '+o.code;const p=document.createElement('p');p.textContent=`${({ia:'CRYPTO',super:'SUPER CRYPTO',limited:'Temps limité',daily:'Produits de revenu quotidien',team:'Produit d’équipe'}[o.category]||'CRYPTO')} · ${o.duration_label} · achat ${money(o.min_amount_cfa)} · total affiché ${money(o.display_value_cfa)} · limite personnelle ${o.default_user_limit} · stock ${o.stock_limit===null?'illimité':Math.max(0,Number(o.stock_limit)-Number(o.stock_used))+' / '+o.stock_limit}${o.category==='limited'?' · réservations payées '+Number(o.paid_reservations||0)+' · restantes '+Number(o.reservations_remaining||0)+' · portefeuille produit '+money(o.product_wallet_balance_cfa||0):''}`;const status=document.createElement('p');status.className='offer-publication-status';status.textContent=o.published&&o.active?'Publié et visible dans le compte utilisateur':(o.published&&!o.active?'Publication suspendue — offre désactivée':(o.active?'Brouillon — non visible des utilisateurs':'Désactivée — non visible des utilisateurs'));title.append(h,p,status);if(o.image_url){const img=document.createElement('img');img.src=o.image_url;img.alt='Illustration de '+o.name;img.style.cssText='width:76px;height:62px;object-fit:cover;border-radius:8px;margin-right:12px';card.append(img)}const actions=document.createElement('div');actions.className='offer-row-actions';const edit=document.createElement('button');edit.className='outline';edit.type='button';edit.textContent='Modifier';edit.addEventListener('click',()=>fillOfferForm(o));const addAction=(label,action,primary=false)=>{const btn=document.createElement('button');btn.className=primary?'primary':'outline';btn.type='button';btn.textContent=label;btn.disabled=['show','republish'].includes(action)&&!o.active;btn.addEventListener('click',async()=>{const prompts={hide:'Suspendre ce produit ? Il restera dans le catalogue utilisateur mais les achats seront bloqués.',show:'Lancer/afficher ce produit dans l’espace utilisateur ?',remove:o.category==='limited'?'Supprimer définitivement ce produit du catalogue utilisateur ? Les réservations, achats et traces financières déjà enregistrés seront conservés dans l’administration.':'Retirer cette offre de l’espace utilisateur ? Elle restera conservée dans l’administration.',republish:'Republier cette offre dans l’espace utilisateur ?'};if(!confirm(prompts[action]))return;btn.disabled=true;try{await api(`/api/admin/offers/${o.id}/publication`,{method:'POST',body:JSON.stringify({action})});await loadAdminOffers()}catch(e){alert(e.message);btn.disabled=false}});actions.append(btn)};status.textContent=o.removed?'Retirée — conservée dans l’administration':(!o.published?'Brouillon — non visible des utilisateurs':(!o.active?'Désactivée — non visible des utilisateurs':(!o.purchase_enabled?'Masquée — visible, achats bloqués':'Affichée — achats autorisés')));if(o.removed)addAction('Republier','republish',true);else if(o.published){if(o.purchase_enabled)addAction(o.category==='limited'?'Suspendre':'Masquer','hide');else addAction(o.category==='limited'?'Lancer le produit':'Afficher','show',true);addAction(o.category==='limited'?'Supprimer définitivement':'Retirer','remove')}else{addAction(o.category==='limited'?'Lancer le produit':'Afficher','show',true);addAction(o.category==='limited'?'Supprimer définitivement':'Retirer','remove')}actions.append(edit);card.append(title,actions);host.append(card)}}catch(e){$('#offer-list').textContent=e.message}}

$('#preview-user-space')?.addEventListener('click',()=>{const offers=window.smileAdminOffers||[];if(!offers.length){$('#offer-status').textContent='Aucun produit à afficher.';return}const url='/preview.html?data='+encodeURIComponent(JSON.stringify(offers));window.open(url,'smile-user-preview','noopener,noreferrer')});

function fillOfferForm(o){const f=$('#offer-form');for(const k of ['id','code','name','description','category'])f.elements[k].value=o[k]??(k==='category'?'ia':'');f.elements.durationLabel.value=o.duration_label;f.elements.minAmount.value=o.min_amount_cfa;f.elements.displayValue.value=o.display_value_cfa;f.elements.defaultUserLimit.value=o.default_user_limit;f.elements.stockLimit.value=o.stock_limit??'';f.elements.saleStartAt.value=o.sale_start_at?new Date(o.sale_start_at).toISOString().slice(0,16):'';f.elements.saleEndAt.value=o.sale_end_at?new Date(o.sale_end_at).toISOString().slice(0,16):'';f.elements.reservationAmounts.value=(o.reservation_amounts_cfa||[]).join(', ');f.elements.productWalletBalance.value=o.product_wallet_balance_cfa??0;f.elements.reservationsRemaining.value=o.reservations_remaining??0;f.dataset.imageUrl=o.image_url||'';const preview=$('#offer-image-preview');preview.hidden=!o.image_url;if(o.image_url)preview.src=o.image_url;f.elements.active.checked=o.active;f.elements.reason.value='';f.elements.code.disabled=true;$('#offer-form-title').textContent='Modifier une offre';$('#offer-status').textContent='Les souscriptions déjà payées conservent leurs conditions. Seul le stock restant recevra les nouvelles conditions.';f.scrollIntoView({behavior:'smooth',block:'start'})}
function resetOfferForm(){const f=$('#offer-form');f.reset();f.elements.id.value='';f.elements.category.value='ia';f.elements.code.disabled=false;f.elements.defaultUserLimit.value=2;f.elements.stockLimit.value='';f.elements.saleStartAt.value='';f.elements.saleEndAt.value='';f.elements.reservationAmounts.value='';f.elements.productWalletBalance.value=0;f.elements.reservationsRemaining.value=0;f.elements.reason.value='';f.dataset.imageUrl='';$('#offer-image-preview').hidden=true;f.elements.active.checked=true;$('#offer-form-title').textContent='Ajouter une offre';$('#offer-status').textContent=''}
$('#offer-reset')?.addEventListener('click',resetOfferForm);
async function loadOfferConditionsAudit(){const host=$('#offer-conditions-audit');if(!host)return;host.textContent='Chargement…';try{const d=await api('/api/admin/offer-conditions-audit');host.innerHTML='';if(!d.history.length){host.textContent='Aucune modification de conditions enregistrée.';return}for(const h of d.history){const row=document.createElement('article');row.className='deposit-row';const title=document.createElement('b'),meta=document.createElement('p'),details=document.createElement('p');title.textContent=`${h.offer_name} · ${h.code}`;meta.textContent=`${new Date(h.created_at).toLocaleString('fr-FR')} · Administrateur : ${h.actor_name||'—'} · Motif : ${h.reason}`;const old=h.old_conditions||{},next=h.new_conditions||{};details.textContent=`Avant : ${old.durationLabel||'—'} · ${money(old.minAmountCfa||0)} → ${money(old.displayValueCfa||0)} · stock ${old.stockLimit===null?'illimité':old.stockLimit} | Après : ${next.durationLabel||'—'} · ${money(next.minAmountCfa||0)} → ${money(next.displayValueCfa||0)} · stock ${next.stockLimit===null?'illimité':next.stockLimit}`;row.append(title,meta,details);host.append(row)}}catch(e){host.textContent=e.message}}
$('#refresh-offer-audit')?.addEventListener('click',loadOfferConditionsAudit);

$('#offer-image-preview')?.addEventListener('error',e=>{e.currentTarget.hidden=true});$('#offer-form')?.elements.imageFile?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){$('#offer-status').textContent='Image PNG, JPEG ou WebP de 5 Mo maximum.';e.target.value='';return}const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});try{const d=await api('/api/admin/offers/image',{method:'POST',body:JSON.stringify({dataUrl})});e.currentTarget.form.dataset.imageUrl=d.imageUrl;const img=$('#offer-image-preview');img.src=d.imageUrl;img.hidden=false;$('#offer-status').textContent='Image téléversée. Enregistrez l’offre pour confirmer.'}catch(err){$('#offer-status').textContent=err.message}});
$('#offer-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b={code:f.elements.code.value,name:f.elements.name.value,description:f.elements.description.value,category:f.elements.category.value,durationLabel:f.elements.durationLabel.value,minAmount:f.elements.minAmount.value,displayValue:f.elements.displayValue.value,defaultUserLimit:f.elements.defaultUserLimit.value,stockLimit:f.elements.stockLimit.value,imageUrl:f.dataset.imageUrl||'',active:f.elements.active.checked,reason:f.elements.reason.value,saleStartAt:f.elements.saleStartAt.value?new Date(f.elements.saleStartAt.value).toISOString():null,saleEndAt:f.elements.saleEndAt.value?new Date(f.elements.saleEndAt.value).toISOString():null,reservationAmounts:f.elements.reservationAmounts.value.split(',').map(x=>Number(x.trim())).filter(Number.isFinite),productWalletBalance:f.elements.productWalletBalance.value,reservationsRemaining:f.elements.reservationsRemaining.value};try{const id=f.elements.id.value;await api(id?`/api/admin/offers/${id}`:'/api/admin/offers',{method:id?'PUT':'POST',body:JSON.stringify(b)});$('#offer-status').textContent=id?'Conditions modifiées pour le stock restant. Les souscriptions déjà payées gardent leur snapshot initial.':'Offre créée en brouillon. Elle reste invisible aux utilisateurs jusqu’à votre publication manuelle.';resetOfferForm();loadAdminOffers();loadQuotaOffers()}catch(err){$('#offer-status').textContent=err.message}});


// Traitement manuel des dépôts : validation après vérification effective du paiement.
async function loadDeposits(){const host=$('#deposit-list');if(!host)return;host.innerHTML='<p class="hint">Chargement des dépôts…</p>';try{const d=await api('/api/admin/deposits');host.innerHTML='';if(!d.deposits.length){host.innerHTML='<p class="hint">Aucun dépôt enregistré.</p>';return}for(const dep of d.deposits){const card=document.createElement('article');card.className='deposit-row';const info=document.createElement('div');const title=document.createElement('b');title.textContent=`${dep.name} · ${money(dep.amount_cfa)}`;const meta=document.createElement('p');meta.textContent=`${dep.public_id} · ${dep.email} · ${(dep.provider==='tmoney'?'Mixx (TMoney)':String(dep.provider).toUpperCase())} · Envoyé depuis ${dep.payer_phone||'non renseigné'} · Reçu sur ${dep.recipient_phone||'ancien numéro non archivé'} · Réf. ${dep.provider_reference||'non renseignée'} · ${new Date(dep.created_at).toLocaleString('fr-FR')}`;const state=document.createElement('span');state.className='deposit-state '+dep.status;state.textContent=dep.status==='pending'?'En attente':dep.status==='approved'?'Validé':'Rejeté';info.append(title,meta,state);card.append(info);if(dep.status==='pending'){const actions=document.createElement('div');actions.className='deposit-actions';const approve=document.createElement('button');approve.className='primary';approve.type='button';approve.textContent='Paiement reçu — Valider';approve.addEventListener('click',async()=>{const confirmedReference=prompt(`Après vérification dans le compte marchand ${(dep.provider==='tmoney'?'Mixx (TMoney)':String(dep.provider).toUpperCase())}, recopiez la référence réellement reçue :`,dep.provider_reference||'');if(!confirmedReference||confirmedReference.trim()!==String(dep.provider_reference||'')){alert('Référence différente ou absente. Dépôt non validé.');return}const confirmedAmount=Number(prompt(`Saisissez le montant réellement reçu en FCFA (attendu : ${Number(dep.amount_cfa)}).`,' '+Number(dep.amount_cfa)));if(!Number.isSafeInteger(confirmedAmount)||confirmedAmount!==Number(dep.amount_cfa)){alert('Montant différent. Dépôt non validé.');return}if(!confirm(`J’atteste avoir vérifié directement la réception de ${money(dep.amount_cfa)} sur le compte marchand ${(dep.provider==='tmoney'?'Mixx (TMoney)':String(dep.provider).toUpperCase())}, avec la référence ${confirmedReference}. Le portefeuille sera crédité.`))return;approve.disabled=true;try{await api('/api/admin/deposits/approve',{method:'POST',body:JSON.stringify({depositId:dep.id,confirmedReceived:true,confirmedReference:confirmedReference.trim(),confirmedAmount})});$('#deposit-status').textContent='Dépôt validé et portefeuille crédité.';loadDeposits();refresh()}catch(e){$('#deposit-status').textContent=e.message;approve.disabled=false}});const reject=document.createElement('button');reject.className='outline';reject.type='button';reject.textContent='Rejeter';reject.addEventListener('click',async()=>{const reason=prompt('Motif du rejet (obligatoire) :');if(!reason||reason.trim().length<3)return;reject.disabled=true;try{await api('/api/admin/deposits/reject',{method:'POST',body:JSON.stringify({depositId:dep.id,reason:reason.trim()})});$('#deposit-status').textContent='Dépôt rejeté.';loadDeposits();refresh()}catch(e){$('#deposit-status').textContent=e.message;reject.disabled=false}});actions.append(approve,reject);card.append(actions)}host.append(card)}}catch(e){host.innerHTML='';$('#deposit-status').textContent=e.message}}
$('#refresh-deposits')?.addEventListener('click',loadDeposits);


