$('#export-subscriptions')?.addEventListener('click',()=>{if(!lastSubscriptionData.length){$('#investment-status').textContent='Aucune souscription à exporter pour les filtres actuels.';return}const cols=['id','public_id','name','email','offer_code_snapshot','offer_name_snapshot','amount_cfa','total_return_cfa','status','created_at','due_at','duration_label_snapshot','min_amount_cfa_snapshot','display_value_cfa_snapshot'];const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\uFEFF'+[cols.join(';'),...lastSubscriptionData.map(r=>cols.map(c=>esc(r[c])).join(';'))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='smile-souscriptions-'+new Date().toISOString().slice(0,10)+'.csv';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);$('#investment-status').textContent=`Export CSV créé (${lastSubscriptionData.length} souscription(s)).`});
