// Tableau de supervision des dépôts et retraits Mobile Money.
async function loadPaymentSupervision(){
 const status=$('#payment-supervision-status');if(!status)return;status.textContent='Chargement des transactions…';
 const params=new URLSearchParams({from:$('#payment-from')?.value||'',to:$('#payment-to')?.value||'',provider:$('#payment-provider')?.value||'',status:$('#payment-status')?.value||''});
 try{const d=await api('/api/admin/payment-supervision?'+params.toString()),s=d.stats||{};
  $('#ps-deposits-pending').textContent=s.deposits_pending_count??0;$('#ps-deposits-pending-total').textContent=money(s.deposits_pending_cfa);
  $('#ps-deposits-approved').textContent=s.deposits_confirmed_count??0;$('#ps-deposits-approved-total').textContent=money(s.deposits_confirmed_cfa);
  $('#ps-withdrawals-pending').textContent=s.withdrawals_pending_count??0;$('#ps-withdrawals-pending-total').textContent=money(s.withdrawals_pending_cfa);
  $('#ps-withdrawals-paid').textContent=s.withdrawals_paid_count??0;$('#ps-withdrawals-paid-total').textContent=money(s.withdrawals_paid_gross_cfa);
  $('#ps-duplicates').textContent=d.duplicate_reference_rows??0;$('#ps-total').textContent=s.total_count??0;
  const providers=$('#payment-provider-breakdown');providers.innerHTML='';if(!(d.providers||[]).length){providers.textContent='Aucune transaction pour ces filtres.'}else for(const p of d.providers){const row=document.createElement('div');row.className='provider-row';const name=document.createElement('b'),detail=document.createElement('span');name.textContent=(p.provider==='tmoney'?'Mixx (TMoney)':String(p.provider).toUpperCase());detail.textContent=`${p.transaction_count} opération(s) · Dépôts validés : ${money(p.deposits_confirmed_cfa)} · Retraits payés : ${money(p.withdrawals_paid_cfa)}`;row.append(name,detail);providers.append(row)}
  const body=$('#payment-transaction-rows');body.innerHTML='';const rows=d.transactions||[];if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=7;td.textContent='Aucune transaction pour ces filtres.';tr.append(td);body.append(tr)}else for(const t of rows){const tr=document.createElement('tr');const vals=[new Date(t.created_at).toLocaleString('fr-FR'),t.kind==='deposit'?'Dépôt':'Retrait',`${t.name} · ${t.public_id}`,(t.provider==='tmoney'?'Mixx (TMoney)':String(t.provider||'').toUpperCase()),t.provider_reference||'—',money(t.amount_cfa),t.status==='pending'?'En attente':t.status==='approved'?'Validé':t.status==='paid'?'Payé':'Rejeté'];for(const value of vals){const td=document.createElement('td');td.textContent=value;tr.append(td)}body.append(tr)}
  status.textContent=`Données actualisées le ${new Date(d.generated_at).toLocaleString('fr-FR')}. Les références dupliquées sont des alertes à vérifier, pas une preuve de fraude.`;
 }catch(e){status.textContent=e.message}
}
$('#payment-filters')?.addEventListener('submit',e=>{e.preventDefault();loadPaymentSupervision()});$('#refresh-payments')?.addEventListener('click',loadPaymentSupervision);$('#payment-clear')?.addEventListener('click',()=>{$('#payment-filters').reset();loadPaymentSupervision()});

// Recherche universelle dans toutes les tables de la base SMILE.
$('#global-search-form')?.addEventListener('submit',async e=>{
 e.preventDefault();const term=$('#global-search-query').value.trim();const status=$('#global-search-status'),host=$('#global-search-results');host.replaceChildren();
 if(term.length<2){status.textContent='Entrez au moins 2 caractères.';return}
 status.textContent='Recherche dans toutes les données SMILE…';
 try{
  const data=await api('/api/admin/search?q='+encodeURIComponent(term));const results=data.results||[];
  const groups=new Map();for(const r of results){if(!groups.has(r.table))groups.set(r.table,[]);groups.get(r.table).push(r)}
  if(!results.length){const p=document.createElement('p');p.className='hint';p.textContent='Aucun résultat trouvé dans les tables consultables.';host.append(p)}
  for(const [table,items] of groups){const section=document.createElement('section');section.className='global-search-group';const h=document.createElement('h3');h.textContent=`${table} (${items.length})`;section.append(h);
   for(const item of items){const row=document.createElement('article');row.className='deposit-row';const info=document.createElement('div'),b=document.createElement('b'),p=document.createElement('p');
    b.textContent=item.primary_key?`ID : ${item.primary_key}`:table;
    const vals=Object.entries(item.fields||{}).map(([k,v])=>`${k} : ${v}`).slice(0,6);p.textContent=vals.join(' · ');info.append(b,p);row.append(info);section.append(row)}host.append(section)}
  status.textContent=`Recherche terminée : ${data.total||0} résultat(s) affiché(s) sur toutes les tables. Maximum 100 résultats.`;
 }catch(err){status.textContent=err.message}
});


