// Rubrique Contrôle : les identifiants et secrets restent exclusivement côté serveur.
$('#control-unlock-form')?.addEventListener('submit',async e=>{e.preventDefault();const password=new FormData(e.currentTarget).get('password');$('#control-unlock-status').textContent='Vérification…';try{await api('/api/admin/control/unlock',{method:'POST',body:JSON.stringify({password})});const form=e.currentTarget;if(form && typeof form.reset==='function')form.reset();$('#control-content').hidden=false;$('#control-unlock-status').textContent='Accès accordé pour 30 minutes.';loadSpecialAccounts();loadSpecialCommissions()}catch(err){$('#control-unlock-status').textContent=err.message}});
async function loadSpecialAccounts(){const host=$('#control-accounts');if(!host)return;host.textContent='Chargement…';try{const d=await api('/api/admin/control/accounts');host.innerHTML='';for(const a of d.accounts){const card=document.createElement('article');card.className='deposit-row';const info=document.createElement('div'),title=document.createElement('b'),meta=document.createElement('p'),state=document.createElement('span');title.textContent=`${a.name} · ${a.phone} · ${a.public_id}`;meta.textContent=`Solde du portefeuille : ${money(a.balance)} · Commissions reçues : ${money(a.commissions_total)} · Nombre : ${a.commissions_count} · Taux : 12 %`;state.className='deposit-state '+(a.active?'approved':'rejected');state.textContent=a.active?'Activé':'Désactivé';info.append(title,meta,state);const btn=document.createElement('button');btn.type='button';btn.className=a.active?'outline':'primary';btn.textContent=a.active?'Désactiver':'Activer';btn.onclick=async()=>{btn.disabled=true;try{await api(`/api/admin/control/accounts/${a.special_account_id}/status`,{method:'POST',body:JSON.stringify({active:!a.active})});$('#control-status').textContent='Statut enregistré dans l’historique.';loadSpecialAccounts()}catch(err){$('#control-status').textContent=err.message;btn.disabled=false}};card.append(info,btn);host.append(card)}if(!d.accounts.length)host.textContent='Aucun compte spécial provisionné. Configurez les variables serveur puis redémarrez SMILE.'}catch(e){host.textContent=e.message}}
async function loadSpecialCommissions(){const host=$('#control-commissions');if(!host)return;host.textContent='Chargement…';try{const d=await api('/api/admin/control/commissions');host.innerHTML='';if(!d.commissions.length){host.textContent='Aucune commission enregistrée.';return}for(const c of d.commissions){const row=document.createElement('article');row.className='deposit-row';const info=document.createElement('div'),title=document.createElement('b'),meta=document.createElement('p'),state=document.createElement('span');title.textContent=`${c.account_name} · ${c.status==='credited'?'Commission créditée':'Commission perdue'}`;meta.textContent=`Nouvel inscrit : ${c.depositor_name} (${c.depositor_phone}) · Dépôt #${c.deposit_id} · Taux 12 % · ${money(c.amount_cfa)} · ${new Date(c.created_at).toLocaleString('fr-FR')}`;state.className='deposit-state '+(c.status==='credited'?'approved':'rejected');state.textContent=c.status==='credited'?'Créditée':'Perdue (compte inactif)';info.append(title,meta,state);row.append(info);host.append(row)}for(const a of (d.audit||[])){const row=document.createElement('article');row.className='deposit-row';const info=document.createElement('div'),title=document.createElement('b'),meta=document.createElement('p');title.textContent=`Journal de contrôle · ${a.account_name||'Compte spécial'} · ${a.action}`;meta.textContent=`Administrateur : ${a.actor_name||'Système'} · ${new Date(a.created_at).toLocaleString('fr-FR')} · ${JSON.stringify(a.details||{})}`;info.append(title,meta);row.append(info);host.append(row)}}catch(e){host.textContent=e.message}}
$('#control-refresh')?.addEventListener('click',loadSpecialAccounts);$('#control-history-refresh')?.addEventListener('click',loadSpecialCommissions);


// Configuration des numéros marchands : un numéro actif au maximum par opérateur.
async function loadDepositSettings(){
 try{const d=await api('/api/admin/deposit-settings');for(const provider of ['flooz','tmoney']){const f=$('#deposit-settings-'+provider);if(!f)continue;const v=(d.settings||[]).find(x=>x.provider===provider)||{};f.elements.phone.value=v.phone||'';f.elements.enabled.checked=!!v.enabled;$('#deposit-settings-'+provider+'-status').textContent=v.enabled?'Numéro actif : '+v.phone:'Numéro désactivé';}}
 catch(e){for(const provider of ['flooz','tmoney']){const el=$('#deposit-settings-'+provider+'-status');if(el)el.textContent=e.message}}
}
for(const provider of ['flooz','tmoney'])$('#deposit-settings-'+provider)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),status=$('#deposit-settings-'+provider+'-status');b.disabled=true;try{const d=await api('/api/admin/deposit-settings/'+provider,{method:'PUT',body:JSON.stringify({phone:f.elements.phone.value.trim(),enabled:f.elements.enabled.checked})});status.textContent=d.setting.enabled?'Numéro enregistré et actif : '+d.setting.phone:'Numéro enregistré mais désactivé.';}catch(err){status.textContent=err.message}finally{b.disabled=false}});
$('#refresh-deposit-settings')?.addEventListener('click',loadDepositSettings);
